# Helpers for the release script.

version_gt() {
  local IFS=. i x y
  local -a a=($1) b=($2)
  local n=${#a[@]}
  [ "${#b[@]}" -gt "$n" ] && n=${#b[@]}
  for ((i = 0; i < n; i++)); do
    x=$((10#${a[i]:-0}))
    y=$((10#${b[i]:-0}))
    if [ "$x" -gt "$y" ]; then
      return 0
    fi
    if [ "$x" -lt "$y" ]; then
      return 1
    fi
  done
  return 1
}

bump_patch() {
  local v=$1 head last
  case $v in
    *.*) head=${v%.*}.; last=${v##*.} ;;
    *) head=; last=$v ;;
  esac
  printf '%s%d\n' "$head" $((10#$last + 1))
}

log_line() {
  printf '%s\n' "$*"
}

read_lines() {
  local n=0 line
  while IFS= read -r line || [ -n "$line" ]; do
    n=$((n + 1))
    printf '%d: %s\n' "$n" "$line"
  done < "$1"
}

count_lines() {
  grep -c '' "$1"
}

run_logged() {
  local status
  "$@"
  status=$?
  if [ "$status" -eq 0 ]; then
    echo ok >> "$RUN_LOG"
  else
    echo "failed ($status)" >> "$RUN_LOG"
  fi
  return "$status"
}

